function Breakdown({ breakdown }) {
  const total = Object.values(breakdown).reduce((a, b) => a + b, 0) || 1;
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
      {[5, 4, 3, 2, 1].map((n) => {
        const pct = Math.round((breakdown[n] / total) * 100);
        return (
          <div key={n} style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ fontSize: 12, width: 10, color: INK }}>{n}</span>
            <Star size={11} fill={GOLD} color={GOLD} />
            <div style={{ flex: 1, height: 6, background: "#FBEBD9", borderRadius: 4, overflow: "hidden" }}>
              <div style={{ width: `${pct}%`, height: "100%", background: WINE, borderRadius: 4 }} />
            </div>
            <span style={{ fontSize: 11, width: 26, color: INK_SOFT, textAlign: "right" }}>{breakdown[n]}</span>
          </div>
        );
      })}
    </div>
  );
}

