// ---- impulsionamento (divulgação paga do perfil da babá) ----

/** Converte as compras reais (GET /boosts/mine) no formato local
 * { [planKey]: { ativo, dias } } que MaeView/BabaCard já leem. */
function reduzirBoostsAtivos(rows) {
  const agora = new Date();
  const mapa = {};
  (rows || []).forEach((r) => {
    const ativo = r.status === "ativo" && r.expiresAt && new Date(r.expiresAt) > agora;
    if (ativo && (!mapa[r.planKey] || new Date(r.expiresAt) > new Date(mapa[r.planKey].expiresAt))) {
      mapa[r.planKey] = { ativo: true, dias: r.duracaoDias, expiresAt: r.expiresAt };
    }
  });
  return mapa;
}

function CadastroMae({
  onConcluir, onVoltar, titulo = "Cadastro de pai ou mãe",
  corFundo = PAPER, corTexto = INK, corBotao, labelBairro = "Seu bairro", pedirFilhos = false,
}) {
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [cep, setCep] = useState("");
  const [bairro, setBairro] = useState("");
  const [cidade, setCidade] = useState("");
  const [uf, setUf] = useState("");
  const [quantidadeFilhos, setQuantidadeFilhos] = useState("");
  const [erro, setErro] = useState("");
  const [carregando, setCarregando] = useState(false);
  const [buscandoCep, setBuscandoCep] = useState(false);
  const [statusBuscaCep, setStatusBuscaCep] = useState(null); // null | "ok" | "naoEncontrado" | "invalido"

  const buscarCep = async () => {
    const limpo = cep.replace(/\D/g, "");
    if (limpo.length !== 8) {
      setStatusBuscaCep("invalido");
      return;
    }
    setBuscandoCep(true);
    setStatusBuscaCep(null);
    try {
      const resposta = await fetch(`https://viacep.com.br/ws/${limpo}/json/`);
      const dados = await resposta.json();
      if (!resposta.ok || dados.erro) {
        setStatusBuscaCep("naoEncontrado");
      } else {
        setBairro(dados.bairro || dados.localidade || "");
        setCidade(dados.localidade || "");
        setUf(dados.uf || "");
        setStatusBuscaCep("ok");
      }
    } catch {
      setStatusBuscaCep("naoEncontrado");
    } finally {
      setBuscandoCep(false);
    }
  };

  const concluir = async () => {
    if (carregando) return;
    if (!nome.trim() || !email.trim() || !senha.trim() || !bairro.trim() || (pedirFilhos && !quantidadeFilhos)) {
      setErro("Preencha todos os campos para continuar.");
      return;
    }
    if (senha.length < 8) {
      setErro("A senha precisa ter pelo menos 8 caracteres.");
      return;
    }
    setErro("");
    setCarregando(true);
    try {
      await onConcluir({
        nome: nome.trim(), email: email.trim(), senha, bairro: bairro.trim(), cidade: cidade.trim(), uf: uf.trim(),
        quantidadeFilhos: pedirFilhos ? Number(quantidadeFilhos.replace("+", "")) : undefined,
      });
    } catch (e) {
      setErro(e.message || "Não foi possível concluir o cadastro. Tente novamente.");
    } finally {
      setCarregando(false);
    }
  };

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", padding: "24px 24px", background: corFundo, overflowY: "auto" }}>
      <button onClick={onVoltar} style={{ background: "none", border: "none", cursor: "pointer", alignSelf: "flex-start", marginBottom: 14 }}>
        <ChevronLeft size={20} color={corTexto} />
      </button>
      <p style={{ fontFamily: "Fraunces, serif", fontSize: 19, color: corTexto, fontWeight: 600, marginBottom: 18 }}>
        {titulo}
      </p>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <input style={inputStyle} placeholder="Nome completo" value={nome} onChange={(e) => setNome(e.target.value)} />
        <input style={inputStyle} type="email" placeholder="seuemail@exemplo.com" value={email} onChange={(e) => setEmail(e.target.value)} />
        <input style={inputStyle} type="password" placeholder="Crie uma senha (mín. 8 caracteres)" value={senha} onChange={(e) => setSenha(e.target.value)} />

        <div style={{ display: "flex", gap: 8 }}>
          <input
            style={{ ...inputStyle, flex: 1 }} placeholder="CEP" inputMode="numeric"
            value={cep} onChange={(e) => setCep(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && buscarCep()}
          />
          <button type="button" onClick={buscarCep} disabled={buscandoCep} style={{
            display: "flex", alignItems: "center", gap: 6, background: corTexto, color: corFundo,
            border: "none", borderRadius: 12, padding: "0 16px", cursor: "pointer",
            fontFamily: "Manrope, sans-serif", fontWeight: 700, fontSize: 12.5, whiteSpace: "nowrap",
          }}>
            <MapPin size={14} /> {buscandoCep ? "Buscando…" : "Buscar"}
          </button>
        </div>
        {statusBuscaCep && (
          <p style={{ fontSize: 10.5, color: statusBuscaCep === "ok" ? FOREST : ERROR, margin: "-6px 0 0" }}>
            {statusBuscaCep === "ok" && "Bairro localizado automaticamente pelo CEP."}
            {statusBuscaCep === "naoEncontrado" && "CEP não encontrado — preencha o bairro manualmente abaixo."}
            {statusBuscaCep === "invalido" && "Digite um CEP com 8 números."}
          </p>
        )}
        <input style={inputStyle} placeholder={labelBairro} value={bairro} onChange={(e) => setBairro(e.target.value)} />
        {pedirFilhos && (
          <div>
            <p style={{ fontSize: 12, color: corTexto, fontFamily: "Manrope, sans-serif", marginBottom: 8 }}>Quantos filhos você tem?</p>
            <ChoicePills options={["1", "2", "3", "4+"]} value={quantidadeFilhos} onChange={setQuantidadeFilhos} />
          </div>
        )}
        {erro && <p style={{ fontSize: 11.5, color: ERROR, fontFamily: "Manrope, sans-serif", margin: 0 }}>{erro}</p>}
        <button className="shine-cta" onClick={concluir} disabled={carregando} style={{ ...btnPrimary, width: "100%", marginTop: 6, opacity: carregando ? 0.6 : 1, cursor: carregando ? "default" : "pointer", ...(corBotao || {}) }}>
          {carregando ? "Cadastrando..." : "Concluir cadastro"}
        </button>
      </div>
    </div>
  );
}

